/* Secondary screens */
.screen{min-height:calc(100vh - 146px)}.page-head{display:flex;align-items:flex-end;justify-content:space-between;margin:9px 0 18px}.page-head h1{font:30px Georgia,serif;margin:3px 0}.page-head p{margin:0;color:var(--muted);font-size:12px}.btn{background:#292a31;border:1px solid #44454e;border-radius:7px;padding:9px 13px;font-weight:650;font-size:11px}.btn.gold-btn{background:linear-gradient(130deg,#d2ac61,#aa7840);border-color:#e3c179;color:#20190f}.btn:disabled{opacity:.45;cursor:not-allowed}.panel-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}.item-card,.zone-card{padding:13px;border:1px solid var(--line);border-radius:10px;background:var(--panel);position:relative}.item-card.selected,.zone-card.selected{border-color:#bd9857;box-shadow:0 0 0 1px #bd985733}.item-icon{width:37px;height:37px;border-radius:9px;background:#282831;display:grid;place-items:center;font-size:20px;margin-bottom:9px}.item-name{font-weight:700;font-size:12px}.item-meta{font-size:10px;color:var(--muted);margin:4px 0 9px}.rarity{font-size:9px;letter-spacing:1px;text-transform:uppercase;font-weight:800}.rarity.Common{color:#c3c4c6}.rarity.Uncommon{color:#7dc889}.rarity.Rare{color:#76a9ed}.rarity.Epic{color:#c184ec}.rarity.Legendary{color:#e4b54e}.rarity.Mythic{color:#ef7b83}.rarity.Divine{color:#80ddd5}.card-actions{display:flex;gap:6px;flex-wrap:wrap}.item-count{position:absolute;right:11px;top:11px;background:#36363d;border-radius:10px;padding:2px 6px;font-size:10px}.slots{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.slot{min-height:83px;padding:9px;background:#212228;border:1px solid #34353d;border-radius:8px}.slot strong{display:block;font-size:9px;color:var(--muted);letter-spacing:.8px;text-transform:uppercase;margin-bottom:8px}.slot div{font-size:11px;font-weight:650}.slot.empty div{color:#66666e;font-weight:500}.zone-card{min-height:165px;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden}.zone-card:before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 80% 10%,var(--zone,#53634a)33,transparent 65%);opacity:.2;pointer-events:none}.zone-card>*{position:relative}.zone-card h3{margin:0;font:19px Georgia,serif}.zone-card p{color:var(--muted);font-size:10px;margin:6px 0}.zone-index{font-size:9px;color:var(--gold);letter-spacing:1px}.zone-footer{display:flex;justify-content:space-between;align-items:center;font-size:10px}.section-bar{margin:20px 0 10px;display:flex;align-items:center;justify-content:space-between}.section-bar h2{font:18px Georgia,serif;margin:0}.toast{position:fixed;left:50%;bottom:86px;transform:translateX(-50%);z-index:30;background:#2c2d33;border:1px solid #55515b;border-radius:8px;padding:10px 15px;box-shadow:0 8px 22px #0008;font-size:12px;animation:fadeToast 2.4s forwards}@keyframes fadeToast{0%,75%{opacity:1}100%{opacity:0;pointer-events:none}}.modal-backdrop{position:fixed;inset:0;background:#08090bc9;z-index:20;display:grid;place-items:center;padding:18px}.modal{width:min(520px,100%);max-height:92vh;overflow:auto;background:#1a1b20;border:1px solid #4b4750;border-radius:14px;padding:23px;box-shadow:0 25px 90px #000a}.modal h1{font:28px Georgia,serif;margin:0 0 5px}.modal p{color:var(--muted);font-size:12px}.form-label{display:block;margin:13px 0 6px;font-size:10px;color:#c6c2cb;text-transform:uppercase;letter-spacing:1px}.text-input{width:100%;border:1px solid #45454d;background:#24252c;border-radius:7px;padding:11px;color:#f4f0e9;outline:none}.choice-row{display:flex;gap:7px;flex-wrap:wrap}.choice{background:#25262d;border:1px solid #44454d;border-radius:7px;padding:9px 11px;font-size:11px}.choice.on{border-color:var(--gold);color:var(--gold);background:#342d22}.toast-btn{cursor:pointer}.detail-row{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #33343b;font-size:11px}.empty-state{text-align:center;padding:35px;color:var(--muted);border:1px dashed #414149;border-radius:10px}.tab-strip{display:flex;gap:7px;overflow:auto;margin:10px 0 14px}.tab-chip{white-space:nowrap;background:#24252b;color:#aaa5ae;border:1px solid #3a3b42;border-radius:20px;padding:7px 11px;font-size:10px}.tab-chip.on{color:var(--gold);border-color:#927748}.profile-banner{padding:18px;display:flex;gap:15px;align-items:center;background:linear-gradient(110deg,#28252d,#1b1c21)}.big-avatar{width:70px;height:70px;border-radius:50%;border:1px solid #766248;background:#332f33;display:grid;place-items:center;font-size:32px}.notice{border-left:2px solid var(--cyan);padding:9px 12px;color:#b8c2c1;font-size:10px;background:#202529;margin-top:12px}.craft-recipe{display:flex;justify-content:space-between;align-items:center;padding:12px;border-bottom:1px solid #34353b}.craft-recipe:last-child{border:0}.forge-count{font-size:10px;color:var(--muted)}
@media(max-width:760px){.app-shell{padding:13px 12px 88px}.topbar{margin-bottom:13px;padding-bottom:12px}.layout{grid-template-columns:1fr;gap:11px}.layout .right-column{display:grid;grid-template-columns:1fr 1fr;align-items:start;gap:10px}.layout .right-column .log-card{grid-column:1/-1}.battlefield{height:290px}.enemy-figure{right:4%;width:165px;height:190px}.player-figure{left:8%;width:130px;height:190px}.attack-row{gap:7px;padding:10px}.skill-btn{width:66px}.attack-btn{min-height:58px}.panel-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.zone-card{min-height:148px}.brand-title{font-size:15px}.currency{padding:7px 8px;min-width:65px}.screen{min-height:calc(100vh - 136px)}}
@media(max-width:380px){.layout .right-column{grid-template-columns:1fr}.layout .right-column .log-card{grid-column:auto}.battlefield{height:260px}.player-figure{left:3%;width:114px}.enemy-figure{right:1%;width:150px}.skill-btn{width:58px;font-size:9px}.panel-grid{gap:7px}.brand-sub{font-size:8px}}

const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE_KEY='aetheria_save_v1';
const zones=[
 {name:'Greendale',tone:'#748b5e',foes:['Mossling','Thornback','Wildfang'],boss:'Elder Treant',desc:'Soft hills and ancient roots.'},
 {name:'Ironcrag',tone:'#927b6b',foes:['Crag Boar','Cave Kobold','Ironhide'],boss:'The Forge Warden',desc:'A scarred range of iron and stone.'},
 {name:'Venomwood',tone:'#597c63',foes:['Sporeling','Venom Stalker','Briar Witch'],boss:'The Mire Queen',desc:'A forest that breathes poison.'},
 {name:'Mistgrave',tone:'#77788e',foes:['Grave Wisp','Hollow Knight','Dusk Hound'],boss:'Warden of the Veil',desc:'Where forgotten souls wander.'},
 {name:'Frostpeak',tone:'#7994a8',foes:['Frostling','Icebound Wolf','Glacier Golem'],boss:'The White Tyrant',desc:'A crown of endless winter.'},
 {name:'Sunscorch Desert',tone:'#b8864e',foes:['Dune Scorpion','Ash Viper','Sunbound'],boss:'The Sand Sovereign',desc:'Gold dunes beneath a burning sky.'},
 {name:'Ashen Dominion',tone:'#a56258',foes:['Cinder Fiend','Ashen Reaver','Ember Drake'],boss:'The Ashen Lord',desc:'A kingdom forged in flame.'},
 {name:'Tower of Eternity',tone:'#8272ad',foes:['Voidling','Astral Sentinel','Time Eater'],boss:'The Eternal',desc:'Climb beyond the edge of time.'}
];
const slots=['Weapon','Head','Chest','Hands','Legs','Feet','Amulet','Ring','Relic'];
const rarityOrder=['Common','Uncommon','Rare','Epic','Legendary','Mythic','Divine'];
const classInfo={Warrior:{icon:'⚔️',weapon:'Oathblade',armor:'Iron Vanguard',skills:['Shield Slam','Whirlwind'],skillIcons:['⬟','⟳'],power:1.25},Mage:{icon:'✦',weapon:'Starweave Staff',armor:'Runesilk',skills:['Comet','Arcane Nova'],skillIcons:['☄','✧'],power:1.05},Assassin:{icon:'◈',weapon:'Gloamfang Daggers',armor:'Nightveil',skills:['Ambush','Fan of Blades'],skillIcons:['◉','✣'],power:1.13}};
const fresh=()=>({version:1,profile:null,level:1,xp:0,hp:100,mp:60,gold:100,gems:12,essence:0,shards:0,prestige:0,zone:0,stage:1,kills:0,screen:'battle',inventory:[],equipment:{},skillLv:{},unlocks:{},cosmetics:{},log:['Welcome to Aetheria. Your journey begins here.'],seenBosses:[],activeBuff:0,enemy:{},lastDaily:'',selectedItem:null,shopTab:'Outfit'});
let state;try{state=JSON.parse(localStorage.getItem(SAVE_KEY))||fresh()}catch{state=fresh()}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){console.warn('Save unavailable',e)}}
function power(){const c=classInfo[state.profile?.class||'Warrior'];return Math.floor((8+state.level*3+state.prestige*5+equipStat())*c.power)}
function equipStat(){return Object.values(state.equipment).reduce((a,x)=>a+(x?.stat||0),0)}
function maxHp(){return 100+state.level*18+state.prestige*35+Object.values(state.equipment).reduce((a,x)=>a+(x?.hp||0),0)}
function maxMp(){return 60+state.level*7+state.prestige*9}
function enemyMax(){const z=state.zone+1,s=state.stage,boss=stageBoss();return Math.floor((34+z*13+s*10)*(boss?5:1)*(1+state.prestige*.12))}
function stageBoss(){return state.stage%10===0}
function enemyName(){const z=zones[state.zone],n=state.stage;return stageBoss()?z.boss:(z.foes[(n-1)%z.foes.length]+(n>3?' '+['Scout','Stalker','Ravager'][Math.floor((n-1)/3)%3]:''))}
function log(text){state.log.unshift(text);state.log=state.log.slice(0,20)}
function gainXp(amount){state.xp+=amount;while(state.xp>=xpNeed()){state.xp-=xpNeed();state.level++;state.hp=maxHp();state.mp=maxMp();log(`Level up! You reached level ${state.level}.`);toast(`Level ${state.level} reached!`)} }
function xpNeed(){return 45+state.level*32}
function toast(msg){const old=$('.toast');if(old)old.remove();const t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2450)}
function makeItem(slot,rarity='Common',tier=3,cls=null){const ri=rarityOrder.indexOf(rarity),base=4+ri*5+(3-tier)*3+state.level;const names={Weapon:['Dawncleaver','Moon Staff','Whisperfang'],Head:['Crown of Embers','Veil Hood','Iron Circlet'],Chest:['Aetherplate','Runesilk Mantle','Nightweave'],Hands:['Grips of Might','Starbound Gloves','Shadow Wraps'],Legs:['Greaves of Resolve','Astral Leggings','Dusk Trousers'],Feet:['Skystriders','Frostwalkers','Silent Steps'],Amulet:['Heart of Aether','Oath Pendant','Wraith Charm'],Ring:['Ring of Echoes','Sunspark Band','Void Loop'],Relic:['Phoenix Sigil','Ancient Rune','Fate Shard']};const icons={Weapon:'⚔',Head:'♜',Chest:'▣',Hands:'◉',Legs:'⛨',Feet:'⌁',Amulet:'◇',Ring:'◌',Relic:'✦'};return {id:Math.random().toString(36).slice(2,10),slot,name:(names[slot]||['Aether Relic'])[Math.floor(Math.random()*3)],rarity,tier,cls,stat:base,hp:Math.floor(base*3),icon:icons[slot]||'◇',count:1}}
function addItem(item){const match=state.inventory.find(x=>x.name===item.name&&x.rarity===item.rarity&&x.tier===item.tier&&x.cls===item.cls);if(match)match.count++;else state.inventory.push(item)}
function hit(amount,skillName='Strike',kind='attack'){
 if(!state.profile)return;const foeMax=enemyMax();state.enemy.hp=state.enemy.hp??foeMax;let damage=amount;const crit=Math.random()<(state.profile.class==='Assassin'?.24:.08);if(crit)damage=Math.floor(damage*1.8);if(state.activeBuff)damage=Math.floor(damage*1.35);state.enemy.hp=Math.max(0,state.enemy.hp-damage);animateHit(damage,crit,kind);log(`${crit?'Critical! ':''}${skillName} deals ${damage} damage.`);if(state.enemy.hp<=0){defeatEnemy();return}scheduleRetaliation();save();render()}
function animateHit(dmg,crit,kind){const f=$('.enemy-figure');if(f){f.classList.remove('hit');void f.offsetWidth;f.classList.add('hit')}const arena=$('.battlefield');if(arena){const d=document.createElement('div');d.className='damage-float';d.style.left=`${58+Math.random()*18}%`;d.style.top=`${32+Math.random()*18}%`;d.style.color=crit?'#ffd36b':kind==='magic'?'#a9d8ff':'#fff4cd';d.textContent=(crit?'CRIT ':'')+dmg;arena.appendChild(d);setTimeout(()=>d.remove(),1000)}}
let retaliationTimer=null;function scheduleRetaliation(){if(retaliationTimer)clearTimeout(retaliationTimer);const boss=stageBoss();if(boss){state.bossWarning=true;render();setTimeout(()=>{if(state.enemy.hp>0)enemyStrike(true)},1100)}else retaliationTimer=setTimeout(()=>enemyStrike(false),2400)}
function enemyStrike(boss){if(!state.profile||state.enemy.hp<=0)return;const art=$('.enemy-figure');if(art){art.classList.remove('attack');void art.offsetWidth;art.classList.add('attack')}let dmg=Math.max(3,Math.floor((5+state.zone*3+state.stage*.8)*(boss?2.3:1)-equipStat()*.14));state.hp=Math.max(0,state.hp-dmg);state.bossWarning=false;log(`${enemyName()} hits you for ${dmg}.`);const arena=$('.battlefield');if(arena){const d=document.createElement('div');d.className='damage-float';d.style.left='24%';d.style.top='53%';d.style.color='#ff9a91';d.textContent='−'+dmg;arena.appendChild(d);setTimeout(()=>d.remove(),900)}if(state.hp<=0){state.hp=Math.floor(maxHp()*.4);state.gold=Math.max(0,state.gold-Math.floor(state.gold*.04));log('You retreat to safety and recover. A small gold fee was paid.');toast('Recovered at the sanctuary.')}save();render()}
function defeatEnemy(){const boss=stageBoss(),gold=Math.floor((10+state.zone*7+state.stage*2)*(boss?8:1));state.gold+=gold;state.kills++;gainXp(Math.floor((16+state.zone*8+state.stage*3)*(boss?5:1)));state.essence+=boss?3:1;if(Math.random()<(boss?.9:.24)){const rare=boss?(['Rare','Epic','Legendary'][Math.min(2,Math.floor(Math.random()*3))]):(['Common','Uncommon','Rare'][Math.floor(Math.random()*3)]);const item=makeItem(slots[Math.floor(Math.random()*slots.length)],rare,3,Math.random()<.25?state.profile.class:null);addItem(item);log(`Loot: ${item.name} (${rare}).`);toast(`Found ${item.name}!`)}if(boss){state.gems+=3;state.shards+=2;state.seenBosses.push(`${state.zone}-${state.stage}`);log('Boss reward: 3 Gems and 2 Aether Shards!')}log(`Victory! +${gold} Gold${boss?' · Boss defeated':''}.`);if(state.stage>=20&&state.zone<7){state.zone++;state.stage=1;state.enemy={};toast(`New region unlocked: ${zones[state.zone].name}`)}else{state.stage++;state.enemy={}}if(retaliationTimer)clearTimeout(retaliationTimer);state.bossWarning=false;save();render()}
function basicAttack(){const w=state.equipment.Weapon;hit(Math.max(1,power()+(w?.stat||0)+Math.floor(Math.random()*4)),state.profile.class==='Warrior'?'Cleave':state.profile.class==='Mage'?'Aether Bolt':'Quick Slash',state.profile.class==='Mage'?'magic':'attack')}
function useSkill(index){const info=classInfo[state.profile.class],skills=info.skills,rank=state.skillLv[skills[index]]||1,cost=index===0?18:32;if(state.mp<cost){toast('Not enough Mana.');return}const last=state.cooldowns?.[index]||0;if(Date.now()-last<(index===0?4500:9000)){toast('Ability is still recovering.');return}state.mp-=cost;state.cooldowns=state.cooldowns||{};state.cooldowns[index]=Date.now();const ratio=[2.5,4][index]+rank*.5;hit(Math.floor(power()*ratio),skills[index],state.profile.class==='Mage'?'magic':'skill');save()}
function render(){if(!state.profile){renderCreation();return}if(!state.enemy||!Object.keys(state.enemy).length)state.enemy={hp:enemyMax()};state.hp=Math.min(state.hp,maxHp());state.mp=Math.min(state.mp,maxMp());const root=$('#app');root.innerHTML=`${header()}${state.screen==='battle'?battleScreen():otherScreen()}${nav()}`;bindCommon();if(state.screen==='battle')bindBattle()}
function header(){return `<header class="topbar"><div class="brand"><div class="brand-mark">✦</div><div><div class="brand-title">AETHERIA</div><div class="brand-sub">SHARDS OF THE VEIL</div></div></div><div class="wallet"><div class="currency"><b>◉</b> ${fmt(state.gold)}</div><div class="currency gems"><b>✧</b> ${fmt(state.gems)}</div></div></header>`}
function fmt(n){return Number(n||0).toLocaleString('en-US')}
function nav(){const entries=[['battle','⚔','Battle'],['world','⌖','World'],['gear','◈','Gear'],['forge','⚒','Forge'],['shop','♧','Shop'],['profile','☻','Profile']];return `<nav class="bottom-nav"><div class="nav-inner">${entries.map(([key,icon,label])=>`<button class="nav-btn ${state.screen===key?'active':''}" data-screen="${key}"><i>${icon}</i>${label}</button>`).join('')}</div></nav>`}
function bindCommon(){$$('.nav-btn').forEach(b=>b.onclick=()=>{state.screen=b.dataset.screen;save();render()})}
function $$(sel){return [...document.querySelectorAll(sel)]}
function battleScreen(){const c=state.profile,info=classInfo[c.class],boss=stageBoss(),hp=state.enemy.hp??enemyMax(),pct=Math.max(0,hp/enemyMax()*100);return `<main class="app-shell"><div class="layout"><section class="column"><article class="card"><div class="zone-head"><div><div class="eyebrow">REGION ${String(state.zone+1).padStart(2,'0')} · STAGE ${state.stage}</div><div class="zone-name">${zones[state.zone].name}</div></div><span class="tag">${boss?'BOSS ENCOUNTER':'WILDERNESS'}</span></div><div class="battlefield"><div class="sky-stars"></div><div class="moon"></div><div class="mountain"></div><div class="ground"></div><div class="nameplate"><div class="enemy-name">${esc(enemyName())}</div><div class="enemy-level">Level ${Math.max(1,state.level+state.zone+Math.floor(state.stage/3))} · ${boss?'BOSS':'BEAST'}</div><div class="enemy-hp"><i style="width:${pct}%"></i></div></div>${boss&&state.bossWarning?'<div class="boss-callout">⚠ INCOMING STRIKE</div>':''}<div class="combatant player-figure">${playerSvg(c.class,c.faction)}</div><div class="combatant enemy-figure">${monsterSvg(state.zone,boss)}</div></div><div class="attack-row"><button class="attack-btn" id="attack">⚔ &nbsp;ATTACK<span>Tap to strike · ${power()} ATK</span></button>${info.skills.map((skill,i)=>`<button class="skill-btn" data-skill="${i}" ${state.mp<(i?32:18)?'disabled':''}><span class="skill-icon">${info.skillIcons[i]}</span>${skill}<span class="cooldown" data-cool="${i}">${skillCooldown(i)}</span></button>`).join('')}</div></article><article class="card player-card"><div class="player-head"><div class="avatar">${info.icon}</div><div><div class="player-name">${esc(c.name)}</div><div class="player-class">${c.faction} ${c.class}</div></div><div class="level-pill">LEVEL ${state.level}</div></div><div class="stat-line"><span class="stat-label" style="color:#ee7778">HP</span><div class="bar hp"><i style="width:${state.hp/maxHp()*100}%"></i></div><span class="stat-value">${fmt(state.hp)} / ${fmt(maxHp())}</span></div><div class="stat-line"><span class="stat-label" style="color:#88a9f1">MP</span><div class="bar mp"><i style="width:${state.mp/maxMp()*100}%"></i></div><span class="stat-value">${fmt(state.mp)} / ${fmt(maxMp())}</span></div><div class="xp-row"><span>EXPERIENCE</span><span>${fmt(state.xp)} / ${fmt(xpNeed())}</span></div><div class="xp-bar"><i style="width:${state.xp/xpNeed()*100}%"></i></div></article></section><aside class="column right-column"><article class="card card-pad"><div class="section-title">Adventurer <span class="tag">${c.class}</span></div><div class="right-stats"><div class="stat-tile"><strong>${power()}</strong><span>Attack</span></div><div class="stat-tile"><strong>${equipStat()}</strong><span>Gear</span></div><div class="stat-tile"><strong>${state.prestige}</strong><span>Prestige</span></div></div><div class="detail-row"><span class="muted">Aether Essence</span><b class="cyan">${state.essence}</b></div><div class="detail-row"><span class="muted">Bosses defeated</span><b>${state.seenBosses.length}</b></div></article><article class="card card-pad"><div class="section-title">Equipment <button class="btn" data-goto="gear">View all</button></div><div class="slots" style="margin-top:11px">${slots.slice(0,6).map(s=>slotMarkup(s)).join('')}</div></article><article class="card log-card"><div class="card-pad section-title">Battle log <span class="eyebrow">LIVE</span></div><div class="log">${state.log.map(line=>`<div>› ${esc(line)}</div>`).join('')}</div></article></aside></div></main>`}
function skillCooldown(i){const then=state.cooldowns?.[i]||0,ms=(i===0?4500:9000)-(Date.now()-then);return ms>0?`${Math.ceil(ms/1000)}s`:'READY'}
function slotMarkup(s){const item=state.equipment[s];return `<div class="slot ${item?'':'empty'}"><strong>${s}</strong><div>${item?`${item.icon} ${esc(item.name)}`:'Empty'}</div>${item?`<span class="rarity ${item.rarity}">${item.rarity} · T${item.tier}</span>`:''}</div>`}
function bindBattle(){$('#attack').onclick=basicAttack;$$('[data-skill]').forEach(b=>b.onclick=()=>useSkill(+b.dataset.skill));$$('[data-goto]').forEach(b=>b.onclick=()=>{state.screen=b.dataset.goto;render()})}

