function skillCooldown(i){const then=state.cooldowns?.[i]||0,ms=(i===0?4500:9000)-(Date.now()-then);return ms>0?`${Math.ceil(ms/1000)}s`:'READY'}
function slotMarkup(s){const item=state.equipment[s];return `<div class="slot ${item?'':'empty'}"><strong>${s}</strong><div>${item?`${item.icon} ${esc(item.name)}`:'Empty'}</div>${item?`<span class="rarity ${item.rarity}">${item.rarity} · T${item.tier}</span>`:''}</div>`}
function bindBattle(){$('#attack').onclick=basicAttack;$$('[data-skill]').forEach(b=>b.onclick=()=>useSkill(+b.dataset.skill));$$('[data-goto]').forEach(b=>b.onclick=()=>{state.screen=b.dataset.goto;render()})}

