function playerSvg(cls,faction){const angel=faction==='Angels',trim=angel?'#e7d49c':'#d18b70',armor=cls==='Warrior'?'#777e8d':cls==='Mage'?'#655b99':'#34434d',hair=angel?'#e1c98d':'#342b37';const weapon=cls==='Warrior'?'<path d="M111 112 L145 44" stroke="#d8d8dc" stroke-width="6"/><path d="M135 48l18-18 1 24z" fill="#e6dfcd"/><path d="M102 113l20 8" stroke="#a0784e" stroke-width="6"/>':cls==='Mage'?'<path d="M115 183L130 53" stroke="#826344" stroke-width="5"/><circle cx="131" cy="46" r="11" fill="#91d5e0" opacity=".8"/><path d="M124 45q7-15 14 0q-7 14-14 0" fill="#d5b9ff"/>':'<path d="M102 112l-21 25M119 110l30 19" stroke="#cfd0db" stroke-width="4"/><path d="M78 133l9-15 4 17zM147 128l9-15 2 17z" fill="#d7dee2"/>';return `<svg class="character-svg" viewBox="0 0 170 220" xmlns="http://www.w3.org/2000/svg"><ellipse cx="89" cy="205" rx="48" ry="8" fill="#101013" opacity=".65"/><path d="M48 204l7-57 26-10 34 8 10 59h-26l-8-38-11 38z" fill="${armor}" stroke="#171820" stroke-width="3"/><path d="M54 144l-14 54 19 6 20-47M111 145l18 13 11 42-19 4-17-40" fill="${armor}" stroke="#171820" stroke-width="3"/><path d="M54 144q31-22 60 0l-3 40H62z" fill="${armor}" stroke="${trim}" stroke-width="2"/><path d="M68 137q20 13 37 0l4 15-22 18-21-19z" fill="${trim}" opacity=".75"/><path d="M66 80q-5-26 16-34 25-1 29 24l-4 30-34 1z" fill="${hair}"/><ellipse cx="87" cy="81" rx="23" ry="29" fill="#d8aa88"/><path d="M63 76q2-36 32-34 20 4 20 24-19-9-33-4-7 10-19 14" fill="${hair}"/><path d="M73 80h7m14 0h7" stroke="#29242b" stroke-width="3"/><path d="M83 94q6 4 11 0" fill="none" stroke="#8f5d57" stroke-width="2"/><path d="M63 111l-17 26 11 9 23-22M109 111l19 14-7 13-27-15" fill="#d8aa88" stroke="#26242a" stroke-width="3"/>${weapon}<path d="M70 58q17-13 37 0" stroke="${trim}" stroke-width="4" fill="none"/><circle cx="89" cy="155" r="4" fill="#e8d39b"/><path d="M37 145q-12-9-9-28m103 3q17-10 21-26" stroke="${angel?'#e9dfc2':'#9a6556'}" stroke-width="3" fill="none" opacity=".8"/></svg>`}
function monsterSvg(zone,boss){const hues=['#758356','#89745e','#637d69','#85829b','#779eb3','#bd8a4f','#b66457','#866bb1'];const c=hues[zone],scale=boss?1.14:1;return `<svg class="monster-svg" viewBox="0 0 210 220" xmlns="http://www.w3.org/2000/svg"><g transform="translate(${boss?0:12} 0) scale(${scale})"><ellipse cx="105" cy="205" rx="65" ry="9" fill="#101013" opacity=".66"/><path d="M50 198q-13-49 8-83 9-21 43-23 42 3 55 38 11 33 0 68l-28 3-10-48-17 25-18-22-9 44z" fill="${c}" stroke="#211f25" stroke-width="5"/><path d="M56 133l-26 34 17 10 29-25M151 134l27 21-6 15-30-13" fill="${c}" stroke="#211f25" stroke-width="6"/><path d="M70 103q-7-31 16-48 24-18 47 4 15 16 6 48-21 22-53 4z" fill="${c}" stroke="#211f25" stroke-width="4"/><path d="M77 63L64 36l25 16m40 0 19-25-3 39" fill="${c}" stroke="#211f25" stroke-width="5"/><path d="M82 84h11m24 0h11" stroke="#ffd77b" stroke-width="6" stroke-linecap="round"/><path d="M96 102l9-7 9 7-9 6z" fill="#37222a"/><path d="M76 134q30 16 62 0" fill="none" stroke="#d7b384" stroke-width="4" opacity=".6"/><path d="M87 176l-6 22m45-22 9 22" stroke="#332c2d" stroke-width="7"/>${boss?'<path d="M60 75L45 22l39 35m57 0 35-45-11 58" fill="#d1a96a" stroke="#34262b" stroke-width="5"/><circle cx="104" cy="70" r="5" fill="#fff2bd"/>':''}</g></svg>`}
function otherScreen(){switch(state.screen){case'world':return worldScreen();case'gear':return gearScreen();case'forge':return forgeScreen();case'shop':return shopScreen();case'profile':return profileScreen();default:return battleScreen()}}
function pageHead(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function worldScreen(){return `<main class="app-shell screen">${pageHead('AETHERIA · WORLD','The Shattered Realms','Push forward, challenge dungeons, and claim the next horizon.')}<div class="panel-grid">${zones.map((z,i)=>`<article class="zone-card ${i===state.zone?'selected':''}" style="--zone:${z.tone}"><div><div class="zone-index">REGION ${String(i+1).padStart(2,'0')} ${i>state.zone?'· LOCKED':''}</div><h3>${z.name}</h3><p>${z.desc}</p></div><div class="zone-footer"><span>${i<state.zone?'CLEARED':i===state.zone?`STAGE ${state.stage}`:`UNLOCK AT STAGE ${i===state.zone+1?'20':'PREVIOUS REGION'}`}</span><button class="btn ${i===state.zone?'gold-btn':''}" data-zone="${i}" ${i>state.zone?'disabled':''}>${i===state.zone?'Enter':'Travel'}</button></div></article>`).join('')}</div><div class="section-bar"><h2>Expeditions</h2><span class="tag">SOLO · NO AUTO-COMBAT</span></div><div class="card card-pad"><div class="section-title">${zones[state.zone].name} · Dungeon</div><p class="muted small">A tougher gauntlet with a guaranteed cache at the end. Your attacks remain manual.</p><div class="detail-row"><span>Recommended level</span><b>${Math.max(1,state.zone*6+5)}</b></div><div class="detail-row"><span>Entry fee</span><b class="gold">Free</b></div><button class="btn gold-btn" style="margin-top:12px" id="dungeon">Enter dungeon</button></div></main>`}
function gearScreen(){const tab=state.gearTab||'Equipment',filter=state.filter||'All';const content=tab==='Equipment'?`<div class="card card-pad"><div class="section-title">Nine equipment slots <span class="tag">${equipStat()} GEAR POWER</span></div><div class="slots" style="margin-top:12px">${slots.map(s=>slotMarkup(s)).join('')}</div></div><div class="section-bar"><h2>Backpack</h2><span class="muted small">${state.inventory.reduce((a,x)=>a+x.count,0)} items</span></div><div class="tab-strip">${['All',...slots].map(x=>`<button class="tab-chip ${filter===x?'on':''}" data-filter="${x}">${x}</button>`).join('')}</div>${inventoryMarkup(filter)}`:`<div class="card card-pad"><div class="section-title">Skills & training</div><p class="muted small">Spend Aether Essence to permanently improve your class abilities.</p>${classInfo[state.profile.class].skills.map((s,i)=>`<div class="craft-recipe"><div><b>${classInfo[state.profile.class].skillIcons[i]} ${s}</b><div class="muted small">Rank ${state.skillLv[s]||1} · +50% skill damage per rank</div></div><button class="btn" data-upskill="${i}">Upgrade · ${5+(state.skillLv[s]||1)*4} Essence</button></div>`).join('')}</div>`;return `<main class="app-shell screen">${pageHead('YOUR LOADOUT','Equipment & Skills','Build your legend with class-bound gear and focused training.',`<button class="btn" id="gear-tab">${tab==='Equipment'?'Train skills':'View equipment'}</button>`)}${content}</main>`}
function inventoryMarkup(filter){const arr=state.inventory.filter(x=>filter==='All'||x.slot===filter);if(!arr.length)return '<div class="empty-state">Your pack is empty.<br>Defeat monsters to find your first gear.</div>';return `<div class="panel-grid">${arr.map(x=>`<article class="item-card"><span class="item-count">×${x.count}</span><div class="item-icon">${x.icon}</div><div class="item-name">${esc(x.name)}</div><div class="item-meta">${x.slot} · T${x.tier}${x.cls?` · ${x.cls}`:''}</div><div class="rarity ${x.rarity}">${x.rarity}</div><div class="item-meta">+${x.stat} ATK · +${x.hp} HP</div><div class="card-actions"><button class="btn" data-equip="${x.id}">Equip</button><button class="btn" data-sell="${x.id}">Sell</button></div></article>`).join('')}</div>`}

