function inventoryMarkup(filter){const arr=state.inventory.filter(x=>filter==='All'||x.slot===filter);if(!arr.length)return '<div class="empty-state">Your pack is empty.<br>Defeat monsters to find your first gear.</div>';return `<div class="panel-grid">${arr.map(x=>`<article class="item-card"><span class="item-count">×${x.count}</span><div class="item-icon">${x.icon}</div><div class="item-name">${esc(x.name)}</div><div class="item-meta">${x.slot} · T${x.tier}${x.cls?` · ${x.cls}`:''}</div><div class="rarity ${x.rarity}">${x.rarity}</div><div class="item-meta">+${x.stat} ATK · +${x.hp} HP</div><div class="card-actions"><button class="btn" data-equip="${x.id}">Equip</button><button class="btn" data-sell="${x.id}">Sell</button></div></article>`).join('')}</div>`}
function forgeScreen(){const tab=state.forgeTab||'Fusion',eligible=state.inventory.filter(x=>x.count>=4&&!(x.rarity==='Divine'&&x.tier===1));return `<main class="app-shell screen">${pageHead('THE AETHER FORGE','Forge & Fusion','No gamble. No gear destruction. Four identical items make one stronger item.',`<span class="tag">${state.shards} AETHER SHARDS</span>`)}<div class="tab-strip">${['Fusion','Crafting','Materials'].map(x=>`<button class="tab-chip ${tab===x?'on':''}" data-forgetab="${x}">${x}</button>`).join('')}</div>${tab==='Fusion'?`<div class="card card-pad"><div class="section-title">Fusion rules <span class="cyan">4 → 1</span></div><p class="muted small">Combine four identical items of the same rarity and tier. Tier advances T3 → T2 → T1, then the next rarity at T3.</p><div class="notice">Legendary → Mythic → Divine. A Divine T1 item is already at maximum tier.</div></div><div class="section-bar"><h2>Ready to fuse</h2></div>${eligible.length?`<div class="panel-grid">${eligible.map(x=>{const nxt=fusionTarget(x);return `<article class="item-card"><span class="item-count">×${x.count}</span><div class="item-icon">${x.icon}</div><div class="item-name">${esc(x.name)}</div><div class="item-meta">${x.slot} · T${x.tier} ${x.rarity}</div><div class="item-meta">→ ${nxt.rarity} · Tier ${nxt.tier}</div><button class="btn gold-btn" data-fuse="${x.id}">Fuse 4 items</button></article>`}).join('')}</div>`:'<div class="empty-state">Collect four identical items to unlock a fusion recipe.</div>'}`:tab==='Crafting'?`<div class="card card-pad"><div class="section-title">Blacksmith recipes</div><p class="muted small">Recipes are known to every adventurer. Materials drop from monsters and bosses.</p>${craftRecipes.map(r=>`<div class="craft-recipe"><div><b>${r.icon} ${r.name}</b><div class="muted small">${r.desc} · ${r.cost} Essence + ${r.shards} Shards</div></div><button class="btn" data-craft="${r.id}">Craft</button></div>`).join('')}</div>`:`<div class="panel-grid"><div class="item-card"><div class="item-icon">✧</div><div class="item-name">Aether Essence</div><div class="item-meta">Common crafting material</div><b>${state.essence}</b></div><div class="item-card"><div class="item-icon">⬡</div><div class="item-name">Aether Shards</div><div class="item-meta">Boss crafting material</div><b>${state.shards}</b></div></div>`}</main>`}
function fusionTarget(x){let tier=x.tier,rarity=x.rarity;if(tier>1)tier--;else{tier=3;rarity=rarityOrder[Math.min(rarityOrder.length-1,rarityOrder.indexOf(rarity)+1)]}return {tier,rarity}}
const craftRecipes=[{id:'weapon',name:'Apprentice Weapon',icon:'⚔',desc:'Rare class weapon · +12 ATK',cost:18,shards:0},{id:'armor',name:'Aetherguard Chest',icon:'▣',desc:'Rare chest armor · +10 ATK · +30 HP',cost:16,shards:2},{id:'gem',name:'Gemstone Cache',icon:'✧',desc:'3 Gems',cost:10,shards:1}];
function shopScreen(){const tab=state.shopTab||'Outfit';const goods={Outfit:[['Wanderer Cloak','A travel-worn cosmetic costume.','🧥',40,'gold'],['Celestial Mantle','A radiant ceremonial look.','✨',16,'gems']],Mounts:[['Mossback Stag','A quiet companion for the road.','🦌',80,'gold'],['Emberwing','A tiny phoenix mount.','🐉',24,'gems']],Pets:[['Lantern Moth','Lights the way through the dark.','🦋',55,'gold'],['Cloud Fox','A playful spirit companion.','🦊',18,'gems']],Effects:[['Starfall Trail','A starlit weapon trail.','🌠',70,'gold'],['Voidfire','An otherworldly weapon glow.','🔥',20,'gems']]};return `<main class="app-shell screen">${pageHead('THE WAYFARER’S BAZAAR','Shop','Earn every reward through play. No purchases, timers, or paywalls.',`<span class="tag">FREE TO PLAY</span>`)}<div class="tab-strip">${Object.keys(goods).map(x=>`<button class="tab-chip ${tab===x?'on':''}" data-shoptab="${x}">${x}</button>`).join('')}</div><div class="panel-grid">${goods[tab].map((x,i)=>{const owned=state.cosmetics[x[0]];return `<article class="item-card"><div class="item-icon">${x[2]}</div><div class="item-name">${x[0]}</div><div class="item-meta">${x[1]}</div><div class="item-meta gold">${x[4]==='gold'?'◉ '+x[3]:'✧ '+x[3]}</div><button class="btn ${owned?'':'gold-btn'}" data-buy="${x[0]}" data-price="${x[3]}" data-currency="${x[4]}" ${owned?'disabled':''}>${owned?'Owned':'Unlock'}</button></article>`}).join('')}</div><div class="section-bar"><h2>Earnable Gems</h2><span class="cyan">✧ ${state.gems}</span></div><div class="card card-pad"><div class="section-title">Daily expedition reward <span class="tag">+5 GEMS</span></div><p class="muted small">Claim once per day. Gems also drop from bosses and world milestones.</p><button class="btn gold-btn" id="daily" ${state.lastDaily===new Date().toDateString()?'disabled':''}>${state.lastDaily===new Date().toDateString()?'Claimed today':'Claim daily reward'}</button></div><div class="notice">Everything is earnable in-game. Online leaderboards, PvP, guilds, and co-op bosses are planned integrations; no simulated players are shown.</div></main>`}
function profileScreen(){const p=state.profile;return `<main class="app-shell screen">${pageHead('HERO PROFILE','${esc(p.name)}','Your path through the Veil.') }<div class="card"><div class="profile-banner"><div class="big-avatar">${classInfo[p.class].icon}</div><div><div class="eyebrow">${p.faction} · ${p.gender} · ${p.class}</div><h2 style="font:25px Georgia,serif;margin:4px 0">${esc(p.name)}</h2><div class="muted small">Level ${state.level} adventurer · ${state.kills} victories</div></div></div><div class="card-pad"><div class="right-stats"><div class="stat-tile"><strong>${state.level}</strong><span>Level</span></div><div class="stat-tile"><strong>${state.kills}</strong><span>Victories</span></div><div class="stat-tile"><strong>${state.prestige}</strong><span>Prestige</span></div></div><div class="section-bar"><h2>Legacy</h2></div><p class="muted small">Prestige at level 25 to reset your level and world progress. Keep your items, gems, and cosmetics while gaining permanent power.</p><button id="prestige" class="btn gold-btn" ${state.level<25?'disabled':''}>${state.level<25?`Prestige at level 25 · ${state.level}/25`:'Ascend · Prestige'}</button><div class="notice">Each Prestige grants +5 base attack and +35 maximum HP permanently.</div><div class="section-bar"><h2>Online features</h2></div><p class="muted small">Online leaderboards · PvP · Guilds · Shared boss encounters</p><div class="notice">Connection services are not configured in this offline build. No fake rankings or players are displayed.</div><button id="reset" class="btn" style="margin-top:16px">Delete local save</button></div></div></main>`}

