function renderCreation(){const root=$('#app');root.innerHTML=`<main class="app-shell" style="max-width:760px;padding-top:7vh"><header class="topbar"><div class="brand"><div class="brand-mark">✦</div><div><div class="brand-title">AETHERIA</div><div class="brand-sub">SHARDS OF THE VEIL</div></div></div><span class="tag">CHARACTER CREATION</span></header><section class="card card-pad" style="padding:clamp(18px,5vw,36px)"><div class="eyebrow">YOUR STORY STARTS HERE</div><h1 style="font:34px Georgia,serif;margin:7px 0">Who will answer the call?</h1><p class="muted">Choose your path. Your class determines your weapon, armor, and unique abilities.</p><label class="form-label">Character name</label><input id="char-name" class="text-input" maxlength="16" placeholder="Enter a name" value="Aetherling"><label class="form-label">Gender</label><div class="choice-row" data-select="gender"><button class="choice on" data-val="Male">♂ Male</button><button class="choice" data-val="Female">♀ Female</button></div><label class="form-label">Faction</label><div class="choice-row" data-select="faction"><button class="choice on" data-val="Angels">✧ Angels</button><button class="choice" data-val="Demons">♨ Demons</button></div><label class="form-label">Choose a class</label><div class="panel-grid" data-select="class" style="grid-template-columns:repeat(3,1fr)">${Object.entries(classInfo).map(([name,c],i)=>`<button class="item-card choice ${i===0?'on':''}" data-val="${name}" style="text-align:left"><div class="item-icon">${c.icon}</div><div class="item-name">${name}</div><div class="item-meta">${name==='Warrior'?'Melee · sturdy strikes':name==='Mage'?'Magic · ranged burst':'Fast · critical hits'}</div><div class="muted" style="font-size:9px">${c.weapon}</div></button>`).join('')}</div><button class="btn gold-btn" id="begin" style="width:100%;margin-top:23px;padding:13px">Enter Aetheria →</button><div class="muted small" style="text-align:center;margin-top:12px">Offline adventure · progress saved on this device</div></section></main>`;const choices={gender:'Male',faction:'Angels',class:'Warrior'};$$('[data-select]').forEach(group=>group.querySelectorAll('[data-val]').forEach(b=>b.onclick=()=>{group.querySelectorAll('[data-val]').forEach(x=>x.classList.remove('on'));b.classList.add('on');choices[group.dataset.select]=b.dataset.val}));$('#begin').onclick=()=>{const name=$('#char-name').value.trim().slice(0,16);if(!name){toast('Choose a character name first.');return}state=fresh();state.profile={name,gender:choices.gender,faction:choices.faction,class:choices.class};state.hp=maxHp();state.mp=maxMp();const starter=makeItem('Weapon','Common',3,choices.class);starter.name=classInfo[choices.class].weapon;state.equipment.Weapon=starter;state.screen='battle';log(`Welcome, ${name} the ${choices.class}. Tap ATTACK to strike.`);save();render()}}
function bindOther(){
 $$('#gear-tab').forEach(b=>b.onclick=()=>{state.gearTab=state.gearTab==='Equipment'?'Skills':'Equipment';render()});
 $$('.tab-chip[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});
 $$('.tab-chip[data-forgetab]').forEach(b=>b.onclick=()=>{state.forgeTab=b.dataset.forgetab;render()});
 $$('.tab-chip[data-shoptab]').forEach(b=>b.onclick=()=>{state.shopTab=b.dataset.shoptab;render()});
 $$('.btn[data-zone]').forEach(b=>b.onclick=()=>{const z=+b.dataset.zone;if(z<=state.zone){state.zone=z;state.stage=state.zoneStages?.[z]||1;state.enemy={};state.screen='battle';save();render()}});
 $('#dungeon')?.addEventListener('click',()=>{if(state.gold<0)return;state.dungeon=true;state.stage=10;state.enemy={};state.screen='battle';log('Dungeon entered. A boss guards the chamber.');save();render()});
 $$('.btn[data-equip]').forEach(b=>b.onclick=()=>equipItem(b.dataset.equip));$$('.btn[data-sell]').forEach(b=>b.onclick=()=>sellItem(b.dataset.sell));$$('.btn[data-fuse]').forEach(b=>b.onclick=()=>fuseItem(b.dataset.fuse));
 $$('.btn[data-upskill]').forEach(b=>b.onclick=()=>upgradeSkill(+b.dataset.upskill));$$('.btn[data-craft]').forEach(b=>b.onclick=()=>craftItem(b.dataset.craft));$$('.btn[data-buy]').forEach(b=>b.onclick=()=>buyItem(b));
 $('#daily')?.addEventListener('click',()=>{if(state.lastDaily===new Date().toDateString())return;state.lastDaily=new Date().toDateString();state.gems+=5;log('Daily reward claimed: +5 Gems.');toast('+5 Gems');save();render()});
 $('#prestige')?.addEventListener('click',()=>{if(state.level<25)return;state.prestige++;state.level=1;state.xp=0;state.zone=0;state.stage=1;state.enemy={};state.hp=maxHp();state.mp=maxMp();state.screen='battle';log(`Prestige ${state.prestige}! Your permanent legacy grows stronger.`);toast('Prestige ascension complete!');save();render()});
 $('#reset')?.addEventListener('click',()=>{if(confirm('Delete all Aetheria progress on this device?')){localStorage.removeItem(SAVE_KEY);state=fresh();render()}});
}
function equipItem(id){const x=state.inventory.find(i=>i.id===id);if(!x)return;if(x.cls&&x.cls!==state.profile.class){toast(`Only ${x.cls} can equip this item.`);return}x.count--;if(x.count<=0)state.inventory=state.inventory.filter(i=>i!==x);const old=state.equipment[x.slot];if(old)addItem({...old,id:Math.random().toString(36).slice(2,10),count:1});state.equipment[x.slot]={...x,count:1};state.hp=Math.min(maxHp(),state.hp+x.hp);log(`${x.name} equipped.`);save();render()}
function sellItem(id){const x=state.inventory.find(i=>i.id===id);if(!x)return;const value=Math.max(2,Math.floor((x.stat+x.hp/3)*x.count));state.gold+=value;state.inventory=state.inventory.filter(i=>i!==x);toast(`Sold for ${value} Gold.`);save();render()}
function fuseItem(id){const x=state.inventory.find(i=>i.id===id);if(!x||x.count<4)return;const next=fusionTarget(x);if(next.rarity===x.rarity&&next.tier===x.tier)return;x.count-=4;if(x.count===0)state.inventory=state.inventory.filter(i=>i!==x);const out={...x,id:Math.random().toString(36).slice(2,10),count:1,tier:next.tier,rarity:next.rarity,stat:x.stat+4,hp:x.hp+12};addItem(out);log(`Fusion complete: ${out.name} is now ${out.rarity} T${out.tier}.`);toast(`${out.rarity} T${out.tier} created`);save();render()}
function upgradeSkill(i){const skill=classInfo[state.profile.class].skills[i],rank=state.skillLv[skill]||1,cost=5+rank*4;if(state.essence<cost){toast('Not enough Aether Essence.');return}state.essence-=cost;state.skillLv[skill]=rank+1;toast(`${skill} upgraded to rank ${rank+1}.`);save();render()}
function craftItem(id){const r=craftRecipes.find(x=>x.id===id);if(!r||state.essence<r.cost||state.shards<r.shards){toast('Not enough crafting materials.');return}state.essence-=r.cost;state.shards-=r.shards;if(id==='gem'){state.gems+=3}else{const item=makeItem(id==='weapon'?'Weapon':'Chest','Rare',3,state.profile.class);item.name=id==='weapon'?classInfo[state.profile.class].weapon:'Aetherguard Chest';addItem(item);toast(`${item.name} crafted.`)}save();render()}
function buyItem(b){const price=+b.dataset.price,type=b.dataset.currency,name=b.dataset.buy;if(type==='gold'&&state.gold<price||type==='gems'&&state.gems<price){toast('Not enough currency.');return}if(type==='gold')state.gold-=price;else state.gems-=price;state.cosmetics[name]=true;toast(`${name} unlocked!`);save();render()}

