93: function sellItem(id){const x=state.inventory.find(i=>i.id===id);if(!x)return;const value=Math.max(2,Math.floor((x.stat+x.hp/3)*x.count));state.gold+=value;state.inventory=state.inventory.filter(i=>i!==x);toast(`Sold for ${value} Gold.`);save();render()}
94: function fuseItem(id){const x=state.inventory.find(i=>i.id===id);if(!x||x.count<4)return;const next=fusionTarget(x);if(next.rarity===x.rarity&&next.tier===x.tier)return;x.count-=4;if(x.count===0)state.inventory=state.inventory.filter(i=>i!==x);const out={...x,id:Math.random().toString(36).slice(2,10),count:1,tier:next.tier,rarity:next.rarity,stat:x.stat+4,hp:x.hp+12};addItem(out);log(`Fusion complete: ${out.name} is now ${out.rarity} T${out.tier}.`);toast(`${out.rarity} T${out.tier} created`);save();render()}
95: function upgradeSkill(i){const skill=classInfo[state.profile.class].skills[i],rank=state.skillLv[skill]||1,cost=5+rank*4;if(state.essence<cost){toast('Not enough Aether Essence.');return}state.essence-=cost;state.skillLv[skill]=rank+1;toast(`${skill} upgraded to rank ${rank+1}.`);save();render()}
96: function craftItem(id){const r=craftRecipes.find(x=>x.id===id);if(!r||state.essence<r.cost||state.shards<r.shards){toast('Not enough crafting materials.');return}state.essence-=r.cost;state.shards-=r.shards;if(id==='gem'){state.gems+=3}else{const item=makeItem(id==='weapon'?'Weapon':'Chest','Rare',3,state.profile.class);item.name=id==='weapon'?classInfo[state.profile.class].weapon:'Aetherguard Chest';addItem(item);toast(`${item.name} crafted.`)}save();render()}
